use hec_native_ic::{fp::Fp,jac::{Curve,Div},poly::Poly,instance::factor_base};
use std::{fs,collections::HashSet};
fn main(){let a:Vec<_>=std::env::args().collect();let s=fs::read_to_string(&a[1]).unwrap();let n:Vec<u64>=s.split_whitespace().skip(1).map(|x|x.parse().unwrap()).collect();let(p,ell)=(n[1],n[2]);assert_eq!(p,631);let len=n[3]as usize;let c=Curve::new(Fp::new(p),Poly::from_coeffs(&n[4..4+len]));let cert=fs::read_to_string(&a[2]).unwrap();let order:u64=cert.lines().find_map(|s|s.strip_prefix("unique_multiple=")).unwrap().parse().unwrap();assert_eq!(order,4*ell);let mut group:HashSet<Div>=[c.zero()].into_iter().collect();let fb=factor_base(&c);for(i,&(x,y))in fb.iter().take(16).enumerate(){let q=c.mul(&c.place(x,y),ell);assert!(c.is_zero(&c.mul(&q,4)));let old:Vec<_>=group.iter().cloned().collect();for z in old{for k in 0..4{group.insert(c.add(&z,&c.mul(&q,k)));}}assert!(group.len()<=4);println!("PRIMARY2_SAMPLE index={i} generated_size={}",group.len());}
let mut tors:Vec<_>=group.iter().filter(|d|c.is_zero(&c.mul(d,2))).cloned().collect();tors.sort_by_key(|d|(d.u.n,d.u.c,d.v.n,d.v.c));let mut good=0;for d in &tors{assert!(c.is_valid(d));if c.is_zero(d){continue;}assert_eq!(d.v,Poly::zero());assert!(c.f.divrem(&d.u,&c.fp).1.is_zero());println!("RATIONAL2 degree={} u={:?}",d.u.deg(),&d.u.c[..d.u.n]);if d.u.deg()==3{good+=1;}}
println!("LOCAL_ADMISSION p={p} two_primary_generated={} full_two_primary_certified={} rational_2torsion_observed={} degree3_candidates={good} current_local_chart_admitted={} quotient_constructed=false",group.len(),group.len()==4,tors.len(),good>0);}
